const invoices = $input.first().json.invoices || [];

// Webhook se date range uthao
// Actual webhook node ka name "Webhook" hai
const webhookData = $('Webhook').first().json || {};

// NetSuite script GET method use kar raha hai.
// Dates query params mein aati hain: from_date and to_date.
const requestData = {
  ...(webhookData.query || {}),
  ...(webhookData.body || {}),
};

function normalizeDate(value) {
  if (!value) return null;

  const text = String(value).trim();

  // Format: YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return text;
  }

  // Format: MM/DD/YYYY or M/D/YYYY
  if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(text)) {
    const [month, day, year] = text.split('/');

    const mm = String(month).padStart(2, '0');
    const dd = String(day).padStart(2, '0');

    return `${year}-${mm}-${dd}`;
  }

  const parsedDate = new Date(text);

  if (Number.isNaN(parsedDate.getTime())) {
    return null;
  }

  return parsedDate.toISOString().slice(0, 10);
}

const START_DATE = normalizeDate(
  requestData.startDate ||
  requestData.fromDate ||
  requestData.from_date ||
  requestData.from
);

const END_DATE = normalizeDate(
  requestData.endDate ||
  requestData.toDate ||
  requestData.to_date ||
  requestData.to
);

// Agar NetSuite se date missing ho
if (!START_DATE || !END_DATE) {
  return [
    {
      json: {
        noVoidInvoices: true,
        processingStatus: 'ERROR',
        reportCategory: 'No Void Invoices',
        errorType: 'DATE_RANGE_MISSING',
        errorStage: 'Webhook Date Validation',
        errorMessage: 'Workflow executed from NetSuite, but From Date or To Date was missing/invalid in webhook request.',
        webhookPayload: requestData,
        errorDate: new Date().toISOString(),
      },
    },
  ];
}

// Agar From Date, To Date se bari ho
if (START_DATE > END_DATE) {
  return [
    {
      json: {
        noVoidInvoices: true,
        processingStatus: 'ERROR',
        reportCategory: 'No Void Invoices',
        errorType: 'INVALID_DATE_RANGE',
        errorStage: 'Webhook Date Validation',
        errorMessage: `Invalid date range received from NetSuite. From Date ${START_DATE} cannot be greater than To Date ${END_DATE}.`,
        dateFilterStart: START_DATE,
        dateFilterEnd: END_DATE,
        webhookPayload: requestData,
        errorDate: new Date().toISOString(),
      },
    },
  ];
}

const eligibleInvoices = invoices.filter(inv => {
  const isVoid = String(inv.status || '').toLowerCase() === 'void';

  const isSynced =
    inv.cf_synced_to_netsuite_unformatted === true ||
    String(inv.cf_synced_to_netsuite || '').toLowerCase() === 'true';

  const invoiceDate = inv.invoice_date;

  const isInDateRange =
    invoiceDate &&
    invoiceDate >= START_DATE &&
    invoiceDate <= END_DATE;

  return isVoid && isSynced && isInDateRange;
});

// Agar selected date range mein koi invoice na mile
if (eligibleInvoices.length === 0) {
  return [
    {
      json: {
        noVoidInvoices: true,
        processingStatus: 'ERROR',
        reportCategory: 'No Void Invoices',
        errorType: 'NO_VOID_SYNCED_INVOICES_IN_DATE_RANGE',
        errorStage: 'Zoho Fetch',
        errorMessage: `Workflow executed but no Zoho invoices were found with Status = Void, Synced to NetSuite = TRUE, and invoice_date between ${START_DATE} and ${END_DATE}.`,
        dateFilterStart: START_DATE,
        dateFilterEnd: END_DATE,
        errorDate: new Date().toISOString(),
      },
    },
  ];
}

return eligibleInvoices.map(invoice => ({
  json: {
    ...invoice,
    noVoidInvoices: false,
    dateFilterStart: START_DATE,
    dateFilterEnd: END_DATE,
  },
}));

const invoice = $json;

return [
  {
    json: {
      ...invoice,
      creditMemoExternalId: `Void-${invoice.invoice_number}`,
      zohoInvoiceNumber: invoice.invoice_number,
      zohoInvoiceId: invoice.invoice_id,
      customerName: invoice.customer_name,
      amount: invoice.total,
    },
  },
];

const netsuiteResponse = $json;

// Get original Zoho invoice data from previous Prepare node
const originalInvoice = $('Prepare Credit Memo Key').first().json;

const resultCount = Number(
  netsuiteResponse.count || netsuiteResponse.totalResults || 0
);

return [
  {
    json: {
      ...originalInvoice,
      duplicateCheck: netsuiteResponse,
      duplicateFound: resultCount > 0,
      existingCreditMemoId: netsuiteResponse.items?.[0]?.id || null,
    },
  },
];

