const staticData = $getWorkflowStaticData('global');

if (!staticData.creditMemoReport) {
  staticData.creditMemoReport = {
    startedAt: new Date().toISOString(),
    rows: [],
  };
}

const logRow = {
  invoiceNumber: $json.zohoInvoiceNumber,
  customerName: $json.customerName || $json.customer_name,
  amount: $json.amount,
  status: 'ERROR',
  category: 'Duplicate Credit Memo',
  stage: 'Duplicate Check',
  message: `Credit Memo already exists in NetSuite for Zoho invoice ${$json.zohoInvoiceNumber}`,
