const staticData = $getWorkflowStaticData('global');

const report = staticData.creditMemoReport || {
  startedAt: new Date().toISOString(),
  rows: [],
};

const rows = report.rows || [];
const startedAt = report.startedAt || new Date().toISOString();
const completedAt = new Date().toISOString();

function escapeHtml(value) {
  if (value === null || value === undefined) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function cleanText(value, maxLength = 300) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  return text.length > maxLength ? text.slice(0, maxLength) : text;
}

function normalizeCategory(row) {
  if (row.status === 'SUCCESS') return 'Credit Memos Created';

  if (row.category === 'Duplicate Credit Memo') {
    return 'Skipped Duplicates';
  }

  if (row.category === 'Missing in NetSuite') {
    return 'Invoice missing in NetSuite';
  }

  if (row.category === 'Failed') {
    return 'Failed';
  }

  if (row.category === 'No Void Invoices') {
    return 'No Eligible Void/Synced Invoices';
  }

  return row.category || row.status || 'Other';
}

function normalizeStage(row) {
  const stage = row.stage || '';

  if (stage === 'NetSuite Credit Memo Creation') {
    return 'Credit Memo Creation';
  }

  if (stage === 'Original Invoice Lookup') {
    return 'Original Invoice Lookup';
  }

  if (stage === 'Credit Memo Created and Applied') {
    return 'Credit Memo Created and Applied';
  }

  return stage || 'Workflow Processing';
}

function professionalMessage(row) {
  const category = normalizeCategory(row);
  const invoiceNumber = row.invoiceNumber || 'the invoice';

  if (category === 'Invoice missing in NetSuite') {
    return `Zoho invoice ${invoiceNumber} is voided, but matching invoice was not found in NetSuite.`;
  }

  if (category === 'Skipped Duplicates') {
    return `Credit memo already exists for Zoho invoice ${invoiceNumber}. Skipped to avoid duplicate.`;
  }

  if (category === 'Failed') {
    return `Credit memo could not be created or applied for Zoho invoice ${invoiceNumber}. Please review the NetSuite invoice/application setup.`;
  }

  if (category === 'No Eligible Void/Synced Invoices') {
    return `No eligible void synced invoice found for the selected date range.`;
  }

  return cleanText(row.message || '', 300);
}

const normalizedRows = rows.map(row => ({
  ...row,
  category: normalizeCategory(row),
  stage: normalizeStage(row),
  message: professionalMessage(row),
}));

const successRows = normalizedRows.filter(row => row.category === 'Credit Memos Created');
const duplicateRows = normalizedRows.filter(row => row.category === 'Skipped Duplicates');
const missingRows = normalizedRows.filter(row => row.category === 'Invoice missing in NetSuite');
const failedRows = normalizedRows.filter(row => row.category === 'Failed');
const noEligibleRows = normalizedRows.filter(row => row.category === 'No Eligible Void/Synced Invoices');

const totalReportedItems = normalizedRows.length;
const successCount = successRows.length;
const duplicateCount = duplicateRows.length;
const missingCount = missingRows.length;
const failedCount = failedRows.length;
const noEligibleCount = noEligibleRows.length;

function summaryRow(label, value) {
  return `
    <tr>
      <td style="border:1px solid #ddd;padding:8px;font-weight:bold;">${escapeHtml(label)}</td>
      <td style="border:1px solid #ddd;padding:8px;">${escapeHtml(value)}</td>
    </tr>
  `;
}

function section(title, sectionRows) {
  const bodyRows = sectionRows.length
    ? sectionRows.map((row, index) => `
      <tr>
        <td style="border:1px solid #ddd;padding:8px;">${index + 1}</td>
        <td style="border:1px solid #ddd;padding:8px;">${escapeHtml(row.invoiceNumber || '')}</td>
        <td style="border:1px solid #ddd;padding:8px;">${escapeHtml(row.customerName || '')}</td>
        <td style="border:1px solid #ddd;padding:8px;">${escapeHtml(row.amount || 0)}</td>
        <td style="border:1px solid #ddd;padding:8px;">${escapeHtml(row.stage || '')}</td>
        <td style="border:1px solid #ddd;padding:8px;">${escapeHtml(row.message || '')}</td>
      </tr>
    `).join('')
    : `
      <tr>
        <td colspan="6" style="border:1px solid #ddd;padding:8px;">No records found</td>
      </tr>
    `;

  return `
    <h3>${escapeHtml(title)}: ${sectionRows.length}</h3>
    <table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px;">
      <thead>
        <tr style="background:#f2f2f2;">
          <th style="border:1px solid #ddd;padding:8px;text-align:left;">#</th>
          <th style="border:1px solid #ddd;padding:8px;text-align:left;">Invoice</th>
          <th style="border:1px solid #ddd;padding:8px;text-align:left;">Customer</th>
          <th style="border:1px solid #ddd;padding:8px;text-align:left;">Amount</th>
          <th style="border:1px solid #ddd;padding:8px;text-align:left;">Stage</th>
          <th style="border:1px solid #ddd;padding:8px;text-align:left;">Message</th>
        </tr>
      </thead>
      <tbody>${bodyRows}</tbody>
    </table>
    <br/>
  `;
}

const htmlBody = `
  <div style="font-family:Arial,sans-serif;font-size:13px;color:#222;">
    <h2>Zoho Void Invoice Credit Memo Automation Report</h2>

    <p>Hello,</p>
    <p>The credit memo automation workflow has been completed. Please find the execution summary below.</p>

    <h3>Summary</h3>
    <table style="border-collapse:collapse;width:100%;font-family:Arial,sans-serif;font-size:13px;">
      <tbody>
        ${summaryRow('Started At', startedAt)}
        ${summaryRow('Completed At', completedAt)}
        ${summaryRow('Total Reported Items', totalReportedItems)}
        ${summaryRow('Credit Memos Created', successCount)}
        ${summaryRow('Skipped Duplicates', duplicateCount)}
        ${summaryRow('Invoice missing in NetSuite', missingCount)}
        ${summaryRow('Failed', failedCount)}
        ${summaryRow('No Eligible Void/Synced Invoices', noEligibleCount)}
      </tbody>
    </table>

    <br/>

    ${section('Skipped Duplicates', duplicateRows)}
    ${section('Invoice missing in NetSuite', missingRows)}
    ${section('Failed', failedRows)}
    ${section('No Eligible Void/Synced Invoices', noEligibleRows)}

    <p>Regards,<br/>Credit Memo Automation</p>
  </div>
`;

const textBody =
`Zoho Void Invoice Credit Memo Automation Report

Total Reported Items: ${totalReportedItems}
Credit Memos Created: ${successCount}
Skipped Duplicates: ${duplicateCount}
Invoice missing in NetSuite: ${missingCount}
Failed: ${failedCount}
No Eligible Void/Synced Invoices: ${noEligibleCount}`;

return [
  {
    json: {
      workflowStatus: failedCount > 0 ? 'Completed with Exceptions' : 'Completed',
      startedAt,
      completedAt,
      totalReportedItems,
      successCount,
      duplicateCount,
      missingCount,
      failedCount,
      noEligibleCount,
      subject: `Credit Memo Automation Report - ${new Date().toISOString().slice(0, 10)}`,
      htmlBody,
      html: htmlBody,
      body: htmlBody,
      message: htmlBody,
      textBody,
    },
  },
];

const input = $input.first().json;

// NetSuite invoice response parse karo
const nsInvoice = typeof input.data === 'string'
  ? JSON.parse(input.data)
  : input;

// Original workflow data previous node se uthao
const original = $('Parse Original Invoice Search').item.json;

// Original invoice item lines
const invoiceLines = nsInvoice.item?.items || [];

if (!invoiceLines.length) {
  throw new Error(`Original NetSuite invoice ${original.originalNetSuiteInvoiceNumber} has no item lines.`);
}

// Date: void date agar ho, warna invoice date
const creditMemoDate = original.void_date || original.invoice_date || nsInvoice.tranDate;

// Memo month/year
const memoDate = new Date(`${creditMemoDate}T00:00:00`);
const memoMonthYear = memoDate.toLocaleString('en-US', {
  month: 'long',
  year: 'numeric',
});

// Original invoice ke same item/qty/rate use karo
const creditMemoLines = invoiceLines.map(line => {
  const qty = Number(line.quantity || 1);
  const rate = line.rate !== undefined && line.rate !== null
    ? Number(line.rate)
    : Number(line.amount || 0) / qty;

  return {
    item: {
      id: String(line.item.id),
    },
    quantity: qty,
    rate: rate,
  };
});

const creditMemoPayload = {
  externalId: original.creditMemoExternalId,
  tranDate: creditMemoDate,
  entity: {
    id: String(nsInvoice.entity?.id || original.originalInvoiceSearch.items[0].entity),
  },
  subsidiary: {
    id: '1',
  },
  location: {
    id: '525',
  },
  memo: `Credit Memo for ${memoMonthYear}`,
  item: {
    items: creditMemoLines,
  },
};

return [
  {
    json: {
      ...original,
      originalNetSuiteInvoiceDetail: nsInvoice,
      creditMemoPayload,
    },
  },
];

const staticData = $getWorkflowStaticData('global');

const report = staticData.creditMemoReport || {
  startedAt: new Date().toISOString(),
  rows: [],
};

const summary = $('Build Consolidated Gmail Report').first().json || {};
const rows = report.rows || [];

const completedAt = summary.completedAt || new Date().toISOString();

const safeTimestamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
const parentExternalId = `CM_AUTOMATION_REPORT_${safeTimestamp}_${Math.floor(Math.random() * 100000)}`;

const parentRecordName = `Credit Memo Automation Report - ${new Date().toISOString()}`;

const summaryMessage =
  `Credit Memo Automation completed. ` +
  `Total: ${summary.totalReportedItems || rows.length}, ` +
  `Created: ${summary.successCount || 0}, ` +
  `Skipped: ${summary.duplicateCount || 0}, ` +
  `Missing in NetSuite: ${summary.missingCount || 0}, ` +
  `Failed: ${summary.failedCount || 0}.`;

const parentPayload = {
  externalId: parentExternalId,
  name: parentRecordName,

  custrecordcmar_status: summary.workflowStatus || 'Executed',
  custrecordcmar_started: summary.startedAt || report.startedAt,
  custrecordcmar_completed: completedAt,

  custrecordcmar_total: Number(summary.totalReportedItems || rows.length || 0),
  custrecordcmar_created: Number(summary.successCount || 0),
  custrecordcmar_skipped: Number(summary.duplicateCount || 0),
  custrecordcmar_missing: Number(summary.missingCount || 0),
  custrecordcmar_failed: Number(summary.failedCount || 0),

  custrecordcmar_summary: summaryMessage,
};

return [
  {
    json: {
      parentPayload,
      parentExternalId,
      parentRecordName,
      reportRows: rows,
    },
  },
];

const lookupRaw = $input.first().json || {};

let lookupResponse = lookupRaw;

if (typeof lookupRaw.data === 'string') {
  try {
    lookupResponse = JSON.parse(lookupRaw.data);
  } catch (error) {
    throw new Error('Could not parse SuiteQL lookup response data: ' + error.message);
  }
} else if (lookupRaw.data && typeof lookupRaw.data === 'object') {
  lookupResponse = lookupRaw.data;
}

const items =
  lookupResponse.items ||
  lookupResponse.body?.items ||
  lookupResponse.data?.items ||
  lookupRaw.items ||
  [];

const parentId =
  items?.[0]?.id ||
  items?.[0]?.ID ||
  lookupResponse.id ||
  lookupRaw.id ||
  lookupRaw.body?.id;

if (!parentId) {
  throw new Error(
    'Parent NetSuite report ID was not found from SuiteQL lookup. Actual input was: ' +
    JSON.stringify(lookupRaw)
  );
}

const parentData = $('Prepare NetSuite Parent Report Payload').first().json || {};
const allReportRows = parentData.reportRows || [];

function normalizeCategory(row) {
  if (row.status === 'SUCCESS') return 'Credit Memos Created';

  if (row.category === 'Duplicate Credit Memo') {
    return 'Duplicate Credit Memo Skipped';
  }

  if (row.category === 'Missing in NetSuite') {
    return 'Invoice Not Found in NetSuite';
  }

  if (row.category === 'Failed') {
    return 'Credit Memo Creation Failed';
  }

  if (row.category === 'No Void Invoices') {
    return 'No Eligible Invoice Found';
  }

  return row.category || row.status || 'Other';
}

function normalizeStage(row) {
  const stage = row.stage || '';

  if (stage === 'NetSuite Credit Memo Creation') {
    return 'Credit Memo Creation';
  }

  if (stage === 'Original Invoice Lookup') {
    return 'Original Invoice Lookup';
  }

  return stage || 'Workflow Processing';
}

function cleanText(value, maxLength = 300) {
  if (value === null || value === undefined) return '';
  const text = String(value);
  return text.length > maxLength ? text.slice(0, maxLength) : text;
}

function professionalMessage(row, category) {
  const invoiceNumber = row.invoiceNumber || 'the invoice';

  if (category === 'Invoice Not Found in NetSuite') {
    return `Zoho invoice ${invoiceNumber} is voided, but matching invoice was not found in NetSuite.`;
  }

  if (category === 'Duplicate Credit Memo Skipped') {
    return `Credit memo already exists for Zoho invoice ${invoiceNumber}. Skipped to avoid duplicate.`;
  }

  if (category === 'Credit Memo Creation Failed') {
    return `Credit memo could not be created or applied for Zoho invoice ${invoiceNumber}. Please review the NetSuite invoice/application setup.`;
  }

  if (category === 'No Eligible Invoice Found') {
    return `No eligible void synced invoice found for the selected date range.`;
  }

  return cleanText(row.message || '', 300);
}

// Do not create child record for successful Credit Memo Created rows
const reportRows = allReportRows.filter(row => {
  const category = normalizeCategory(row);
  return category !== 'Credit Memos Created';
});

return reportRows.map(row => {
  const category = normalizeCategory(row);
  const invoiceNumber = row.invoiceNumber || 'No Invoice';
  const customerName = row.customerName || '';
  const stage = normalizeStage(row);
  const message = professionalMessage(row, category);
  const lineName = `${invoiceNumber} - ${category}`;

  return {
    json: {
      childPayload: {
        name: cleanText(lineName, 80),

        custrecordcmal_report: {
          id: String(parentId),
        },
        custrecordcmal_category: cleanText(category, 300),
        custrecordcmal_invoice: cleanText(invoiceNumber, 300),
        custrecordcmal_customer: cleanText(customerName, 300),
        custrecordcmal_amount: Number(row.amount || 0),
        custrecordcmal_stage: cleanText(stage, 300),
        custrecordcmal_message: cleanText(message, 300),
      },
      parentId: String(parentId),
    },
  };
});
